<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title) ?> · EPROC</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.13.1/font/bootstrap-icons.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/admin-lte@4.9.1/dist/css/adminlte.min.css"><style>body{background:linear-gradient(135deg,#12233f,#1d6b73);min-height:100vh}.login-card{max-width:430px;margin:auto;border:0;border-radius:1rem;box-shadow:0 1rem 3rem #07182a66}.brand-mark{width:58px;height:58px;display:grid;place-items:center;border-radius:18px;background:#0d6efd;color:#fff;font-size:1.8rem}</style><style>.field-label{display:inline-block;margin-bottom:.42rem;color:#f1f5f9;font-size:.78rem;font-weight:700;letter-spacing:.045em;line-height:1.3;text-transform:uppercase}.form-control::placeholder{color:#a8b4c5;opacity:1}.form-control{color:#f8fafc;background-color:rgba(15,23,42,.28)}.form-control:focus{color:#fff;background-color:rgba(15,23,42,.42)}</style></head><body class="d-flex align-items-center py-5"><main class="container"><div class="login-card card p-4"><div class="text-center mb-4"><div class="brand-mark mx-auto mb-3"><i class="bi bi-shield-lock"></i></div><h1 class="h3 mb-1">EPROC</h1><p class="text-body-secondary mb-0">Secure procurement workspace</p></div><?php if ($message = session()->getFlashdata('message')): ?><div class="alert alert-success"><?= esc($message) ?></div><?php endif; ?><?php if ($error = session()->getFlashdata('error')): ?><div class="alert alert-danger"><?= esc($error) ?></div><?php endif; ?><form method="post" action="<?= site_url('login') ?>"><?= csrf_field() ?><div class="mb-3"><label class="field-label">Username atau email</label><input class="form-control form-control-lg" name="login" autocomplete="username" required autofocus value="<?=